224	    @Override
225	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
226	        // Idempotent create: when the request carries an 'Idempotency-Key' already seen, return the
227	        // originally created owner with 200 instead of creating (and duplicate-checking) a new one.
228	        String idempotencyKey = currentIdempotencyKey();
229	        if (idempotencyKey != null) {
230	            Integer existingId = idempotencyKeyToOwnerId.get(idempotencyKey);
231	            if (existingId != null) {
232	                Owner existingOwner = this.clinicService.findOwnerById(existingId);
233	                if (existingOwner != null) {
234	                    populateHouseholdSize(existingOwner);
235	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existingOwner), HttpStatus.OK);
236	                }
237	            }
238	        }
239	        List<String> missingFields = new ArrayList<>();
240	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
241	            missingFields.add("firstName");
242	        }
243	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
244	            missingFields.add("lastName");
245	        }
246	        // Normalize each supplied address form up front. The structured fields are preferred when
247	        // present; the flat 'address' input remains accepted for backward compatibility. An owner is
248	        // valid when it supplies an address in EITHER form (a non-blank addressLine1, or the flat
249	        // address). A whitespace-only value collapses to the empty string and counts as absent.
250	        String normalizedAddressLine1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
251	        String normalizedAddressLine2 = normalizeAddress(ownerFieldsDto.getAddressLine2());
252	        String normalizedFlatAddress = normalizeAddress(ownerFieldsDto.getAddress());
253	        boolean hasStructuredAddress = StringUtils.hasText(normalizedAddressLine1);
254	        boolean hasFlatAddress = StringUtils.hasText(normalizedFlatAddress);
255	        if (!hasStructuredAddress && !hasFlatAddress) {
256	            missingFields.add("address");
257	        }
258	        // Compose the stored/returned address: the structured lines when present (addressLine1, with a
259	        // single space and addressLine2 appended when addressLine2 is present), otherwise the flat form.
260	        String composedAddress;
261	        if (hasStructuredAddress) {
262	            composedAddress = StringUtils.hasText(normalizedAddressLine2)
263	                ? normalizedAddressLine1 + " " + normalizedAddressLine2
264	                : normalizedAddressLine1;
265	        } else {
266	            composedAddress = normalizedFlatAddress;
267	        }
268	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
269	            missingFields.add("city");
270	        }
271	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
272	            missingFields.add("telephone");
273	        }
274	        if (!missingFields.isEmpty()) {
275	            throw new InvalidRequestException(missingFields);
276	        }
277	        HttpHeaders headers = new HttpHeaders();
278	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
279	        // A newly created owner is never soft-deleted.
280	        owner.setDeleted(false);
281	        // Store (and later return) the normalized structured lines and the composed address. The
282	        // structured lines are kept only when the structured form was supplied; otherwise they are
283	        // cleared so the response reflects the flat form that was actually used.
284	        owner.setAddressLine1(hasStructuredAddress ? normalizedAddressLine1 : null);
285	        owner.setAddressLine2(hasStructuredAddress && StringUtils.hasText(normalizedAddressLine2)
286	            ? normalizedAddressLine2 : null);
287	        owner.setAddress(composedAddress);
288	        // Normalize the telephone into E.164 form (reject with 400 when it cannot form a valid one).
289	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
290	        owner.setTelephone(normalizedTelephone);
291	        // Normalize the (optional) email: reject a syntactically invalid address, otherwise store it lower-cased.
292	        owner.setEmail(normalizeEmail(owner.getEmail()));
293	        // Validate the (optional) postcode: reject with 400 when present but malformed or out of range
294	        // for the city's region. The value (mapped straight from the request) is stored and returned as given.
295	        validatePostcode(owner.getCity(), owner.getPostcode());
296	        // Reject a supplied registration date that lies in the future (later than the server's current
297	        // date) with a 400 Bad Request. Checked against the raw supplied value, before defaulting below.
298	        if (owner.getRegistrationDate() != null && owner.getRegistrationDate().isAfter(LocalDate.now())) {
299	            throw new InvalidRequestException(List.of("registrationDate"));
300	        }
301	        // Default the (optional) registration date to the server's current date when none was supplied.
302	        if (owner.getRegistrationDate() == null) {
303	            owner.setRegistrationDate(LocalDate.now());
304	        }
305	        // The effective registration date must fall on a business day: when it lands on a Saturday,
306	        // Sunday or a listed public holiday (whether supplied or defaulted above), roll it forward to
307	        // the next non-holiday business day. Every value derived from the registration date below
308	        // (daily create-limit, member id) uses this adjusted date.
309	        owner.setRegistrationDate(rollToBusinessDay(owner.getRegistrationDate()));
310	        // Reject the request once the maximum number of owners for the owner's registration day has
311	        // been reached (100 or more owners already created on that date).
312	        int ownersRegisteredToday = countOwnersRegisteredOn(owner.getRegistrationDate());
313	        if (ownersRegisteredToday >= MAX_OWNERS_PER_DAY) {
314	            throw new DailyOwnerLimitException(owner.getRegistrationDate());
315	        }
316	        // Flag a bulk-signup warning when more than 80 owners had already been created on this
317	        // owner's registration day at the moment this owner was created; otherwise clear it.
318	        owner.setBulkSignupWarning(ownersRegisteredToday > BULK_SIGNUP_WARNING_THRESHOLD);
319	        // Reject the request when the owner's city has already reached its owner capacity.
320	        int ownersInCity = countOwnersInCity(owner.getCity());
321	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
322	            throw new CityCapacityException(owner.getCity());
323	        }
324	        // Flag a capacity warning when the owner's city already holds between 40 and 49 owners
325	        // (approaching the hard limit of 50) at the moment this owner was created; otherwise clear it.
326	        owner.setCapacityWarning(ownersInCity >= CAPACITY_WARNING_THRESHOLD && ownersInCity < MAX_OWNERS_PER_CITY);
327	        // The household is keyed deterministically on (normalizedLastName, postcode): the householdId
328	        // is the first 12 hex characters of the SHA-256 digest of '<normalizedLastName>|<postcode>',
329	        // so any two owners with the same last name and postcode automatically resolve to the same
330	        // household without an explicit opt-in. It is assigned up front so it feeds the household-size
331	        // read-back, the membership-level cap and the household-of-3 points. It is NO LONGER part of
332	        // duplicate detection: that is expressed solely through the identity key below.
333	        String householdId = generateHouseholdId(owner.getLastName(), owner.getPostcode());
334	        owner.setHouseholdId(householdId);
335	        // All duplicate detection is consolidated into this single derived identity key: the SHA-256
336	        // hex of '<normalizedTelephone>|<lowerEmail>|<soundex(lastName)>'. Reject with 409 only when
337	        // the new owner's WHOLE identity key exactly matches a non-deleted existing owner's. Because
338	        // the telephone is part of the key, two owners with the same last name and postcode but
339	        // different telephones have different keys and are both allowed (the second is a soft match,
340	        // see below); only an exact full-key match is a hard duplicate.
341	        String identityKey = owner.getIdentityKey();
342	        boolean identityCollision = this.clinicService.findAllOwners().stream()
343	            .filter(existing -> !existing.isDeleted())
344	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
345	        if (identityCollision) {
346	            throw new DuplicateIdentityException(identityKey);
347	        }
348	        // Soft-match detection: the new owner is not a hard (identity-key) duplicate, but it may
349	        // still be a likely duplicate of an existing owner. Flag it when an existing owner shares
350	        // this owner's soundex(lastName) and postcode while carrying a DIFFERENT identity key. When
351	        // several existing owners match, the one with the lowest id is chosen so the result is
352	        // deterministic.
353	        Owner softMatch = findPossibleDuplicate(owner);
354	        if (softMatch != null) {
355	            owner.setPossibleDuplicate(true);
356	            owner.setPossibleDuplicateOf(softMatch.getId());
357	        } else {
358	            owner.setPossibleDuplicate(false);
359	        }
360	        // Record how many existing owners already share this first name and last name
361	        // (compared case-insensitively) before this owner is created.
362	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
363	        // Assign the unified member id '<REGION><FY><HASH8><CHK>' before persisting.
364	        owner.setMemberId(generateMemberId(owner));
365	        this.clinicService.saveOwner(owner);
366	        // Remember the created owner under the request's idempotency key so a later create repeating
367	        // the same key returns this owner instead of creating a duplicate.
368	        if (idempotencyKey != null) {
369	            idempotencyKeyToOwnerId.put(idempotencyKey, owner.getId());
370	        }
371	        populateHouseholdSize(owner);
372	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
373	        // Cap the new owner's membership level at one above the current maximum among their
374	        // existing household members (no cap when the household has no other member).
375	        applyHouseholdMembershipCap(owner, ownerDto);
376	        // Emit an audit line carrying the new owner's id, unified member id, registration date
377	        // and numeric membership level.
378	        AUDIT.info("owner created id={} memberId={} registrationDate={} membershipLevel={}",
379	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(),
380	            ownerDto.getMembershipLevel());
381	        // Besides the human-readable audit line, emit an immutable structured event carrying a
382	        // monotonically increasing sequence number, the owner id, the owner's primary identifier
383	        // (the unified member id) and the numeric membership level. Serialized once, up front, so
384	        // the logged event cannot change.
385	        AUDIT.info(ownerCreatedEvent(AUDIT_EVENT_SEQ.incrementAndGet(), owner.getId(),
386	            owner.getMemberId(), ownerDto.getMembershipLevel()));
387	        headers.setLocation(UriComponentsBuilder.newInstance()
388	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
389	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
390	    }
