392	    /**
393	     * Build the immutable structured {@code OWNER_CREATED} audit event as a JSON object string:
394	     * {@code {seq, ownerId, memberId, membershipLevel, event:'OWNER_CREATED'}}. The
395	     * {@code memberId} field carries the owner's primary identifier (the unified member id), so the
396	     * event always names the owner's canonical identity. A {@code null} membership level is
397	     * serialized as JSON {@code null}.
398	     *
399	     * @param seq             the monotonically increasing event sequence number
400	     * @param ownerId         the created owner's id
401	     * @param primaryId       the owner's primary identifier (member id)
402	     * @param membershipLevel the owner's numeric membership level, may be {@code null}
403	     * @return the JSON-serialized event
404	     */
405	    private String ownerCreatedEvent(long seq, Integer ownerId, String primaryId, Integer membershipLevel) {
406	        return "{\"seq\":" + seq
407	            + ",\"ownerId\":" + ownerId
408	            + ",\"memberId\":" + jsonString(primaryId)
409	            + ",\"membershipLevel\":" + (membershipLevel == null ? "null" : membershipLevel)
410	            + ",\"event\":\"OWNER_CREATED\"}";
411	    }
