413	    /**
414	     * Render a nullable string as a JSON value: {@code null} for a {@code null} input, otherwise the
415	     * value wrapped in double quotes with the JSON-significant characters escaped.
416	     *
417	     * @param value the value to render, may be {@code null}
418	     * @return the JSON string literal (or the token {@code null})
419	     */
420	    private String jsonString(String value) {
421	        if (value == null) {
422	            return "null";
423	        }
424	        StringBuilder sb = new StringBuilder(value.length() + 2);
425	        sb.append('"');
426	        for (int i = 0; i < value.length(); i++) {
427	            char c = value.charAt(i);
428	            switch (c) {
429	                case '"' -> sb.append("\\\"");
430	                case '\\' -> sb.append("\\\\");
431	                case '\n' -> sb.append("\\n");
432	                case '\r' -> sb.append("\\r");
433	                case '\t' -> sb.append("\\t");
434	                default -> {
435	                    if (c < 0x20) {
436	                        sb.append(String.format("\\u%04x", (int) c));
437	                    } else {
438	                        sb.append(c);
439	                    }
440	                }
441	            }
442	        }
443	        sb.append('"');
444	        return sb.toString();
445	    }
