448	     * Return the current request's {@code Idempotency-Key} header value, or {@code null} when the
449	     * header is absent/blank or there is no bound servlet request.
450	     *
451	     * @return the trimmed idempotency key, or {@code null} when none was supplied
452	     */
453	    private String currentIdempotencyKey() {
454	        org.springframework.web.context.request.RequestAttributes attributes =
455	            org.springframework.web.context.request.RequestContextHolder.getRequestAttributes();
456	        if (attributes instanceof org.springframework.web.context.request.ServletRequestAttributes servletAttributes) {
457	            String key = servletAttributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
458	            if (StringUtils.hasText(key)) {
459	                return key.trim();
460	            }
461	        }
462	        return null;
463	    }
