482	    /**
483	     * Populate the owner's household size: the number of owners sharing this owner's
484	     * {@code householdId} (including the owner itself). An owner with no household is a household
485	     * of one.
486	     *
487	     * @param owner the owner whose household size should be computed and set
488	     */
489	    private void populateHouseholdSize(Owner owner) {
490	        String householdId = owner.getHouseholdId();
491	        if (!StringUtils.hasText(householdId)) {
492	            owner.setHouseholdSize(1);
493	            return;
494	        }
495	        int size = (int) this.clinicService.findAllOwners().stream()
