501	    /**
502	     * Cap the owner's membership level so it never exceeds one above the current maximum membership
503	     * level among the owner's household members (the other non-deleted owners sharing this owner's
504	     * {@code householdId}). When the household has no other member, no cap applies and the level is
505	     * left untouched. Any reduction is written back onto the given dto.
506	     *
507	     * @param owner    the owner whose household members bound the level (excluded from its own household)
508	     * @param ownerDto the mapped dto whose {@code membershipLevel} is capped in place
509	     */
510	    private void applyHouseholdMembershipCap(Owner owner, OwnerDto ownerDto) {
511	        String householdId = owner.getHouseholdId();
512	        if (!StringUtils.hasText(householdId) || ownerDto.getMembershipLevel() == null) {
513	            return;
514	        }
515	        Integer maxMemberLevel = this.clinicService.findAllOwners().stream()
516	            .filter(existing -> !existing.isDeleted())
517	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
518	            .filter(existing -> !java.util.Objects.equals(existing.getId(), owner.getId()))
519	            .map(this::membershipLevelOf)
520	            .max(Integer::compareTo)
521	            .orElse(null);
522	        if (maxMemberLevel != null && ownerDto.getMembershipLevel() > maxMemberLevel + 1) {
523	            ownerDto.setMembershipLevel(maxMemberLevel + 1);
524	        }
525	    }
