540	    /**
541	     * Generate the unified member id formatted {@code <REGION><FY><HASH8><CHK>}, where {@code REGION}
542	     * is the region code derived from the owner's identity (postcode range first, then the
543	     * city-to-region table, otherwise {@code UNKNOWN}), {@code FY} is the two-digit fiscal year that
544	     * the owner's business-day-adjusted registration date falls in, {@code HASH8} is the first eight
545	     * upper-case hex characters of the SHA-256 digest of {@code normalizedTelephone + lastName} (the
546	     * same HASH8 the region-and-hash identity uses), and {@code CHK} is a single Luhn check digit
547	     * computed over the digits of {@code <REGION><FY><HASH8>} (e.g. {@code NSW271A2B3C4D5}).
548	     *
549	     * @param owner the owner whose (already-normalized) telephone, last name, postcode, city and
550	     *              registration date are read
551	     * @return the generated (collision-free) member id
552	     */
553	    private String generateMemberId(Owner owner) {
554	        String region = deriveRegion(owner.getPostcode(), owner.getCity());
555	        String fy = String.format("%02d", fiscalYear(owner.getRegistrationDate()) % 100);
556	        String hash8 = shortSha256Hex(owner.getTelephone() + owner.getLastName(), 8);
557	        String base = region + fy + hash8;
558	        String memberId = base + luhnCheckDigit(base);
559	        return deduplicateMemberId(memberId);
560	    }
561	
562	    /**
563	     * Return a member id that does not collide with any existing owner's member id. When the given
564	     * base id is already unique it is returned unchanged; otherwise {@code -<n>} is appended with the
565	     * smallest {@code n} of 2 or more that makes the result unique (e.g. {@code NSW271A2B3C4D5}, then
566	     * {@code NSW271A2B3C4D5-2}, {@code NSW271A2B3C4D5-3}, ...). The incoming owner is not yet
567	     * persisted, so it never counts as a collision with itself.
568	     *
569	     * @param baseId the computed {@code <REGION><FY><HASH8><CHK>} member id
570	     * @return the de-duplicated member id
571	     */
572	    private String deduplicateMemberId(String baseId) {
573	        java.util.Set<String> existingIds = this.clinicService.findAllOwners().stream()
574	            .map(Owner::getMemberId)
575	            .filter(java.util.Objects::nonNull)
576	            .collect(java.util.stream.Collectors.toSet());
577	        if (!existingIds.contains(baseId)) {
578	            return baseId;
579	        }
580	        int n = 2;
581	        String candidate = baseId + "-" + n;
582	        while (existingIds.contains(candidate)) {
583	            n++;
584	            candidate = baseId + "-" + n;
585	        }
586	        return candidate;
587	    }
588	
589	    /**
590	     * Compute the single Luhn check digit (0-9) over the digits contained in the given value.
591	     * Non-digit characters are ignored. A {@code null} or digit-free value yields a check digit of 0.
592	     *
593	     * @param value the value whose digits the check digit is computed over
594	     * @return the Luhn check digit
595	     */
596	    private int luhnCheckDigit(String value) {
597	        if (value == null) {
598	            return 0;
599	        }
600	        int sum = 0;
601	        boolean doubleDigit = true;
602	        for (int i = value.length() - 1; i >= 0; i--) {
603	            char c = value.charAt(i);
604	            if (c < '0' || c > '9') {
605	                continue;
606	            }
607	            int digit = c - '0';
608	            if (doubleDigit) {
609	                digit *= 2;
610	                if (digit > 9) {
611	                    digit -= 9;
612	                }
613	            }
614	            sum += digit;
615	            doubleDigit = !doubleDigit;
616	        }
617	        return (10 - (sum % 10)) % 10;
618	    }
