620	    /**
621	     * Derive the region code for an owner's identity. The postcode is preferred: when present and it
622	     * falls within a known region's inclusive 4-digit range (NSW 2000-2099, VIC 3000-3099,
623	     * QLD 4000-4099) that region is returned. Otherwise fall back to the pinned city-to-region table
624	     * (Sydney->NSW, Melbourne->VIC, Brisbane->QLD), and finally {@code UNKNOWN} for a city with no
625	     * known region.
626	     *
627	     * @param postcode the owner's postcode, may be {@code null}
628	     * @param city     the owner's city
629	     * @return the derived region code
630	     */
631	    private String deriveRegion(String postcode, String city) {
632	        if (postcode != null && POSTCODE_PATTERN.matcher(postcode).matches()) {
633	            int value = Integer.parseInt(postcode);
634	            for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGE.entrySet()) {
635	                int[] range = entry.getValue();
636	                if (value >= range[0] && value <= range[1]) {
637	                    return entry.getKey();
638	                }
639	            }
640	        }
641	        String region = CITY_REGION.get(city);
642	        return region != null ? region : "UNKNOWN";
643	    }
