645	    /**
646	     * Return the first {@code length} upper-case hex characters of the SHA-256 digest of the UTF-8
647	     * bytes of {@code input}.
648	     *
649	     * @param input  the value to digest
650	     * @param length the number of leading hex characters to return
651	     * @return the truncated upper-case hex digest
652	     */
653	    private String shortSha256Hex(String input, int length) {
654	        try {
655	            byte[] digest = MessageDigest.getInstance("SHA-256")
656	                .digest(input.getBytes(StandardCharsets.UTF_8));
657	            StringBuilder sb = new StringBuilder(digest.length * 2);
658	            for (byte b : digest) {
659	                sb.append(String.format("%02x", b));
660	            }
661	            return sb.substring(0, length).toUpperCase(Locale.ROOT);
662	        } catch (java.security.NoSuchAlgorithmException e) {
663	            throw new IllegalStateException("SHA-256 not available", e);
664	        }
665	    }
