667	    /**
668	     * Roll a registration date forward onto a business day: a Saturday, Sunday or listed public
669	     * holiday is advanced day-by-day until it lands on the next non-holiday weekday, while a date
670	     * that is already a non-holiday weekday is returned unchanged. This is the effective registration
671	     * date that is stored, returned and used for every value derived from it.
672	     *
673	     * @param date the effective registration date (supplied or defaulted)
674	     * @return the same date when it is a non-holiday weekday, otherwise the next non-holiday business day
675	     */
676	    private LocalDate rollToBusinessDay(LocalDate date) {
677	        while (!isBusinessDay(date)) {
678	            date = date.plusDays(1);
679	        }
680	        return date;
681	    }
682	
683	    /**
684	     * A business day is a weekday (Monday to Friday) that is not a listed public holiday.
685	     *
686	     * @param date the date to test
687	     * @return {@code true} when the date is a non-holiday weekday
688	     */
689	    private boolean isBusinessDay(LocalDate date) {
690	        DayOfWeek dayOfWeek = date.getDayOfWeek();
691	        if (dayOfWeek == DayOfWeek.SATURDAY || dayOfWeek == DayOfWeek.SUNDAY) {
692	            return false;
693	        }
694	        return !PUBLIC_HOLIDAYS.contains(date);
695	    }
