755	    /**
756	     * Find the existing owner the given (not-yet-persisted) owner is a soft duplicate of: one that
757	     * shares the owner's {@code soundex(lastName)} and postcode while carrying a DIFFERENT identity
758	     * key. A blank postcode never soft-matches (postcode is required for the match). When several
759	     * owners match, the one with the lowest id is returned so the result is deterministic;
760	     * {@code null} when there is no soft match.
761	     *
762	     * @param owner the incoming owner (with normalized telephone, email and last name resolved)
763	     * @return the lowest-id matching existing owner, or {@code null} when none matches
764	     */
765	    private Owner findPossibleDuplicate(Owner owner) {
766	        if (!StringUtils.hasText(owner.getPostcode())) {
767	            return null;
768	        }
769	        String soundex = Owner.soundex(owner.getLastName());
770	        String identityKey = owner.getIdentityKey();
771	        return this.clinicService.findAllOwners().stream()
772	            .filter(existing -> Owner.soundex(existing.getLastName()).equals(soundex)
773	                && owner.getPostcode().equals(existing.getPostcode())
774	                && !identityKey.equals(existing.getIdentityKey()))
775	            .min(java.util.Comparator.comparing(Owner::getId))
776	            .orElse(null);
777	    }
