779	    /**
780	     * Generate the deterministic household identifier for the given last name and postcode. The value
781	     * is derived from the normalized (case-insensitive, whitespace-collapsed) last name and the
782	     * postcode, so every owner with the same last name and postcode resolves to the same identifier
783	     * automatically. It is the first 12 upper-case hex characters of the SHA-256 digest of
784	     * {@code <normalizedLastName>|<postcode>} (an absent postcode contributes the empty string).
785	     *
786	     * @param lastName the owner's last name
787	     * @param postcode the owner's postcode, may be {@code null}
788	     * @return the deterministic household identifier
789	     */
790	    private String generateHouseholdId(String lastName, String postcode) {
791	        String key = normalizeForComparison(lastName) + "|" + (postcode == null ? "" : postcode);
792	        return shortSha256Hex(key, 12);
793	    }
