795	    /**
796	     * Normalize an owner address for storage: trim and collapse every internal run of whitespace to a
797	     * single space, upper-case the result and expand common street-type abbreviations token by token
798	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} value normalizes
799	     * to the empty string. The result is the canonical form that is stored, returned and used for every
800	     * address comparison (household duplicate detection and the shared household id).
801	     *
802	     * @param address the raw address, may be {@code null}
803	     * @return the normalized address
804	     */
805	    private String normalizeAddress(String address) {
806	        if (address == null) {
807	            return "";
808	        }
809	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
810	        if (collapsed.isEmpty()) {
811	            return "";
812	        }
813	        String[] tokens = collapsed.split(" ");
814	        StringBuilder sb = new StringBuilder(collapsed.length());
815	        for (int i = 0; i < tokens.length; i++) {
816	            if (i > 0) {
817	                sb.append(' ');
818	            }
819	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
820	        }
821	        return sb.toString();
822	    }
