824	    /**
825	     * Normalize a value for identity comparison: trim, collapse every internal run of whitespace to a
826	     * single space and lower-case the result. A {@code null} value normalizes to the empty string.
827	     *
828	     * @param value the raw value, may be {@code null}
829	     * @return the normalized value
830	     */
831	    private String normalizeForComparison(String value) {
832	        if (value == null) {
833	            return "";
834	        }
835	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
836	    }
