838	    /**
839	     * Normalize an optional owner email address. A blank/absent value is treated as "not provided"
840	     * and returns {@code null}. When present, the value must be a syntactically valid address; if it
841	     * is not, an {@link InvalidRequestException} is thrown (mapped to 400 Bad Request). A valid value
842	     * is returned lower-cased.
843	     *
844	     * @param email the raw email from the request payload, may be {@code null}
845	     * @return the lower-cased email, or {@code null} when none was provided
846	     */
847	    private String normalizeEmail(String email) {
848	        if (!StringUtils.hasText(email)) {
849	            return null;
850	        }
851	        if (!EMAIL_PATTERN.matcher(email).matches()) {
852	            throw new InvalidRequestException(List.of("email"));
853	        }
854	        String lowerCased = email.toLowerCase(Locale.ROOT);
855	        // Reject an address whose domain is on the disposable-domain blocklist.
856	        String domain = lowerCased.substring(lowerCased.indexOf('@') + 1);
857	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
858	            throw new InvalidRequestException(List.of("email"));
859	        }
860	        return lowerCased;
861	    }
862	
863	    /**
864	     * Validate an optional owner postcode. A blank/absent value is treated as "not provided" and
865	     * passes (postcode is optional). When present it must be exactly four digits, and when the owner's
866	     * city has a known region (Sydney->NSW, Melbourne->VIC, Brisbane->QLD) the postcode must fall within
867	     * that region's inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known
868	     * region accepts any 4-digit postcode. A violation throws an {@link InvalidRequestException} (mapped
869	     * to 400 Bad Request).
870	     *
871	     * @param city     the owner's city (used to resolve the region)
872	     * @param postcode the raw postcode from the request payload, may be {@code null}
873	     */
874	    private void validatePostcode(String city, String postcode) {
875	        if (!StringUtils.hasText(postcode)) {
876	            return;
877	        }
878	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
879	            throw new InvalidRequestException(List.of("postcode"));
880	        }
881	        String region = CITY_REGION.get(city);
882	        int[] range = region == null ? null : REGION_POSTCODE_RANGE.get(region);
883	        if (range != null) {
884	            int value = Integer.parseInt(postcode);
885	            if (value < range[0] || value > range[1]) {
886	                throw new InvalidRequestException(List.of("postcode"));
887	            }
888	        }
889	    }
890	
891	    /**
892	     * Normalize a telephone into E.164 form. Spaces, dashes and brackets are stripped. A value that
893	     * already carries a leading '+' keeps its country code; otherwise the default country code
894	     * ({@code +61}) is assumed and a single leading '0' is dropped from the national digits. The
895	     * result must be a '+' followed by 8 to 15 digits, otherwise an {@link InvalidRequestException}
896	     * is thrown (mapped to 400 Bad Request).
897	     *
898	     * @param telephone the raw telephone from the request payload
899	     * @return the E.164 string (e.g. {@code +61412345678})
900	     */
901	    private String normalizeTelephone(String telephone) {
902	        String cleaned = TELEPHONE_SEPARATORS.matcher(telephone).replaceAll("");
903	        String candidate;
904	        if (cleaned.startsWith("+")) {
905	            candidate = cleaned;
906	        } else {
907	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
908	            candidate = "+" + DEFAULT_COUNTRY_CODE + national;
909	        }
910	        if (!E164_PATTERN.matcher(candidate).matches()) {
911	            throw new InvalidRequestException(List.of("telephone"));
912	        }
913	        // For country codes with a known fixed national-number length, reject a candidate whose
914	        // national digits (everything after the '+' and the country code) do not match that length.
915	        String digits = candidate.substring(1);
916	        for (Map.Entry<String, Integer> entry : COUNTRY_NATIONAL_LENGTH.entrySet()) {
917	            String countryCode = entry.getKey();
918	            if (digits.startsWith(countryCode)) {
919	                int nationalLength = digits.length() - countryCode.length();
920	                if (nationalLength != entry.getValue()) {
921	                    throw new InvalidRequestException(List.of("telephone"));
922	                }
923	                break;
924	            }
925	        }
926	        return candidate;
927	    }
928	
929	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
930	    @Transactional
931	    @Override
932	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
933	        Owner owner = this.clinicService.findOwnerById(ownerId);
934	        if (owner == null) {
935	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
936	        }
937	        // Soft delete: flag the owner deleted and retain the record rather than removing it. The
938	        // owner is still readable afterwards (with 'deleted' true) but is ignored by the create
939	        // endpoint's duplicate/identity checks.
940	        owner.setDeleted(true);
941	        this.clinicService.saveOwner(owner);
942	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
943	    }
944	
945	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
946	    @Override
947	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
948	        Owner owner = this.clinicService.findOwnerById(ownerId);
949	        if (owner == null) {
950	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
951	        }
952	        HttpHeaders headers = new HttpHeaders();
953	        Pet pet = petMapper.toPet(petFieldsDto);
954	        owner.setId(ownerId);
955	        pet.setOwner(owner);
956	        pet.getType().setName(null);
957	        this.clinicService.savePet(pet);
958	        PetDto petDto = petMapper.toPetDto(pet);
959	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
960	            .buildAndExpand(pet.getId()).toUri());
961	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
962	    }
963	
964	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
965	    @Override
966	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
967	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
968	        if (currentOwner != null) {
969	            Pet currentPet = this.clinicService.findPetById(petId);
970	            if (currentPet != null) {
971	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
972	                currentPet.setName(petFieldsDto.getName());
973	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
974	                this.clinicService.savePet(currentPet);
975	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
976	            }
977	        }
978	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
979	    }
980	
981	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
982	    @Override
983	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
984	        HttpHeaders headers = new HttpHeaders();
985	        Visit visit = visitMapper.toVisit(visitFieldsDto);
986	        Pet pet = new Pet();
987	        pet.setId(petId);
988	        visit.setPet(pet);
989	        this.clinicService.saveVisit(visit);
990	        VisitDto visitDto = visitMapper.toVisitDto(visit);
991	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
992	            .buildAndExpand(visit.getId()).toUri());
993	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
994	    }
995	
996	
997	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
998	    @Override
999	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
1000	        Owner owner = this.clinicService.findOwnerById(ownerId);
1001	        if (owner != null) {
1002	            Pet pet = owner.getPet(petId);
1003	            if (pet != null) {
1004	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
1005	            }
1006	        }
1007	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
1008	    }
1009	}
